import { createRouter as createTanStackRouter } from "@tanstack/react-router";
import { routeTree } from "./routeTree.gen";
import { Unauthorized } from "./components/Unauthorized";

/**
 * Router factory discovered by TanStack Start.
 *
 * Start 1.167+ expects a `getRouter` export from `app/router.tsx` (convention)
 * and calls it both on the server (SSR) and client (hydration). `routeTree.gen.ts`
 * is regenerated by the `@tanstack/router-plugin` (wired via `tanstackStart()`
 * in `vite.config.ts`) on every dev/build.
 */
export function getRouter() {
  const router = createTanStackRouter({
    routeTree,
    defaultPreload: "intent",
    scrollRestoration: true,
    defaultErrorComponent: ({ error }) => {
      // Handle 401 responses from server-side auth guards
      if (error instanceof Response && error.status === 401) {
        return <Unauthorized error={error} />;
      }
      // Fall through to tanstack defaults for other errors
      return null;
    },
  });
  return router;
}

declare module "@tanstack/react-router" {
  interface Register {
    router: ReturnType<typeof getRouter>;
  }
}
